use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == 1,
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            0 <= i as int <= a.len() as int,
            result.len() == i,
            forall|j: int| 0 <= j < result.len() ==> result[j] == 1,
        decreases
            (a.len() - i)
    {
        assert(i < a.len());
        assert(result.len() == i);

        result.push(1);
        i = i + 1;
    }

    assert(!(i < a.len()));
    assert(i == a.len());
    assert(result.len() == a.len());
    assert(forall|k: int| 0 <= k < result.len() ==> result[k] == 1);

    result
}

} // verus!